/* Euno -- The Quiet Room.
   Flat at rest, soft on lift, one blue, motion only as confirmation.
   Every value here is deliberate; see DESIGN.md for the rules. */

/* ---------------------------------------------------------------- tokens */

:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  /* accent: fills and focus. accent-text: tinted text, holds 4.5:1 on bg. */
  --accent: #0071e3;
  --accent-fill: #0071e3;
  --accent-text: #0069d5;
  --danger: #d70015;
  --border: rgba(0, 0, 0, 0.08);
  --field-bg: var(--surface);
  --shadow-float: 0 12px 40px rgba(0, 0, 0, 0.12);
  --header-bg: rgba(245, 245, 247, 0.78);

  --radius: 16px;
  --radius-lg: 24px;

  /* Motion. Strong ease-out for anything entering or responding;
     ease-in-out only for on-screen movement (the name morph). */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --t-fast: 140ms;
  --t-med: 220ms;
  --t-screen: 260ms;
  --t-slow: 420ms;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #000000;
    --surface: #1c1c1e;
    --text: #f5f5f7;
    --muted: #98989d;
    /* Tinted text can afford the brighter blue; filled buttons keep the
       deeper one so white labels hold 4.7:1. */
    --accent: #0a84ff;
    --accent-fill: #0071e3;
    --accent-text: #0a84ff;
    --danger: #ff453a;
    --border: rgba(255, 255, 255, 0.1);
    --shadow-float: 0 12px 40px rgba(0, 0, 0, 0.55);
    --header-bg: rgba(0, 0, 0, 0.72);
  }
}

/* ------------------------------------------------------------------ base */

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -webkit-text-size-adjust: 100%;
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: color-mix(in srgb, var(--accent) 25%, transparent);
}

input,
textarea {
  caret-color: var(--accent);
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  touch-action: manipulation;
  user-select: none;
}

/* Visible keyboard focus everywhere. The transparent outline stays visible
   in forced-colors mode, where box-shadow disappears. */
:focus-visible {
  outline: 2px solid transparent;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 45%, transparent);
}

/* ----------------------------------------------------------------- shell */

.app-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--header-bg);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  backdrop-filter: blur(20px) saturate(180%);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-med) var(--ease-out);
  view-transition-name: app-header;
}

/* The hairline exists only once content has scrolled under the material. */
.app-header[data-scrolled="true"] {
  border-bottom-color: var(--border);
}

.header-inner {
  max-width: 640px;
  margin: 0 auto;
  padding: 14px max(24px, env(safe-area-inset-right)) 14px
    max(24px, env(safe-area-inset-left));
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 52px;
}

.brand {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.app-main {
  max-width: 640px;
  margin: 0 auto;
  padding: 20px max(24px, env(safe-area-inset-right))
    max(48px, env(safe-area-inset-bottom)) max(24px, env(safe-area-inset-left));
}

/* --------------------------------------------------------------- buttons */

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-inline-size: 96px;
  padding: 12px 20px;
  font-size: 17px;
  font-weight: 500;
  color: #fff;
  background: var(--accent-fill);
  border: none;
  border-radius: 980px;
  transition: transform var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out), opacity var(--t-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .btn-primary:hover:not(:disabled) {
    background: color-mix(in srgb, var(--accent-fill) 90%, #000);
  }
}

.btn-primary:active:not(:disabled) {
  transform: scale(0.97);
}

.btn-primary:disabled {
  opacity: 0.55;
  cursor: default;
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  margin: -8px -12px; /* visual size stays text-like; hit target stays big */
  font-size: 17px;
  color: var(--accent-text);
  background: transparent;
  border: none;
  border-radius: 980px;
  transition: transform var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .btn-ghost:hover {
    background: color-mix(in srgb, var(--accent) 10%, transparent);
  }
}

.btn-ghost:active {
  transform: scale(0.97);
}

.btn-ghost svg {
  flex-shrink: 0;
}

/* ---------------------------------------------------------------- fields */

.field {
  width: 100%;
  padding: 14px 16px;
  font: inherit;
  color: var(--text);
  background: var(--field-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: border-color var(--t-fast) var(--ease-out),
    box-shadow var(--t-fast) var(--ease-out);
}

.field::placeholder {
  color: var(--muted);
}

.field:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 15%, transparent);
}

/* Keep autofill from painting the field yellow. */
.field:-webkit-autofill {
  -webkit-box-shadow: 0 0 0 1000px var(--field-bg) inset;
  -webkit-text-fill-color: var(--text);
}

textarea.field {
  min-height: 140px;
  resize: vertical;
  line-height: 1.5;
  field-sizing: content; /* grows with the memory being written */
  max-height: 60vh;
}

/* ---------------------------------------------------------------- search */

.search-wrap {
  position: relative;
}

.search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  translate: 0 -50%;
  color: var(--muted);
  pointer-events: none;
}

.search-input {
  padding-left: 44px;
  padding-right: 44px;
}

.search-clear {
  position: absolute;
  right: 8px;
  top: 50%;
  translate: 0 -50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  color: var(--muted);
  background: transparent;
  border: none;
  border-radius: 50%;
  transition: background var(--t-fast) var(--ease-out),
    color var(--t-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .search-clear:hover {
    color: var(--text);
    background: color-mix(in srgb, var(--muted) 14%, transparent);
  }
}

.search-clear:active {
  transform: scale(0.92);
}

/* --------------------------------------------------------------- results */

.list-label {
  margin: 24px 0 8px;
  font-size: 13px;
  color: var(--muted);
}

.results {
  list-style: none;
  margin: 16px 0 0;
  padding: 0;
}

.result-row {
  width: 100%;
  text-align: left;
  padding: 14px 16px;
  margin-bottom: 8px;
  font-size: 17px;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: transform var(--t-fast) var(--ease-out),
    background var(--t-fast) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .result-row:hover {
    background: color-mix(in srgb, var(--text) 4%, var(--surface));
  }
}

.result-row:active {
  transform: scale(0.985);
}

.add-button {
  margin-top: 16px;
  opacity: 1;
  transition: opacity 150ms var(--ease-out);
}

/* Fade in on appearance; it toggles with typing, so opacity only, no motion. */
@starting-style {
  .add-button {
    opacity: 0;
  }
}

/* ----------------------------------------------------------- empty state */

.empty-state {
  margin: 56px auto 0;
  max-width: 40ch;
  text-align: center;
}

.empty-title {
  margin: 0 0 6px;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-wrap: balance;
}

