import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";
import { authTables } from "@convex-dev/auth/server";

export default defineSchema({
  ...authTables,
  people: defineTable({
    userId: v.id("users"),
    name: v.string(),
    link: v.optional(v.string()),
    context: v.optional(v.string()),
    updatedAt: v.number(),
    // Captured-from-screenshot provenance; all optional so hand-added
    // people need no migration.
    platform: v.optional(v.string()),
    handle: v.optional(v.string()),
    headline: v.optional(v.string()),
    screenshotId: v.optional(v.id("_storage")),
    // Semantic search. embeddedText doubles as the idempotency key so the
    // embed action can skip recomputing an unchanged person.
    embedding: v.optional(v.array(v.float64())),
    embeddedText: v.optional(v.string()),
  })
    .index("by_user", ["userId"])
    .searchIndex("search_name", {
      searchField: "name",
      filterFields: ["userId"],
    })
    .vectorIndex("by_embedding", {
      vectorField: "embedding",
      dimensions: 1536,
      filterFields: ["userId"],
    }),
  // A screenshot waiting to be triaged into a person. Deleted on accept
  // (the file moves to the person) or discard (the file is deleted too).
  captures: defineTable({
    userId: v.id("users"),
    screenshotId: v.id("_storage"),
    status: v.union(
      v.literal("pending"),
      v.literal("ready"),
      v.literal("failed"),
    ),
    extracted: v.optional(
      v.object({
        platform: v.string(),
        name: v.string(),
        handle: v.optional(v.string()),
        headline: v.optional(v.string()),
        bio: v.optional(v.string()),
      }),
    ),
    error: v.optional(v.string()),
  }).index("by_user", ["userId"]),
});

// Plain helpers for the two OpenAI endpoints Euno uses. Not registered
// Convex functions; call these only from actions (they do network IO).
// fetch is available in the default Convex runtime, so no "use node".

export type ExtractedProfile = {
  platform: string;
  name: string;
  handle?: string;
  headline?: string;
  bio?: string;
};

const PLATFORMS = [
  "linkedin",
  "x",
  "instagram",
  "tiktok",
  "github",
  "facebook",
  "threads",
  "bluesky",
  "other",
] as const;

// Strict structured-output schema: every property listed in required,
// optionality expressed as nullable types, per OpenAI strict mode rules.
const EXTRACTION_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["is_profile", "platform", "name", "handle", "headline", "bio"],
  properties: {
    is_profile: {
      type: "boolean",
      description:
        "True only if the screenshot shows a single person's social or professional profile.",
    },
    platform: { type: "string", enum: [...PLATFORMS] },
    name: {
      type: ["string", "null"],
      description: "The person's display name as shown.",
    },
    handle: {
      type: ["string", "null"],
      description: "The username or @handle if visible, without the URL.",
    },
    headline: {
      type: ["string", "null"],
      description: "Their title, tagline, or one-line bio header if visible.",
    },
    bio: {
      type: ["string", "null"],
      description: "A short summary of any visible bio or about text.",
    },
  },
} as const;

const EXTRACTION_PROMPT = [
  "This is a screenshot the user took of someone's social or professional profile.",
  "Identify which platform it is from (branding, layout, UI chrome) and extract",
  "the person's visible details. Only report what is actually visible; never",
  "guess a handle or invent text. If the image is not a person's profile,",
  "set is_profile to false.",
].join(" ");

function apiKey(): string {
  const key = process.env.OPENAI_API_KEY;
  if (key === undefined || key === "") {
    throw new Error(
      "OPENAI_API_KEY is not set on the Convex deployment. Run: npx convex env set OPENAI_API_KEY <key>",
    );
  }
  return key;
}

async function callOpenAI(path: string, body: unknown): Promise<unknown> {
  const response = await fetch(`https://api.openai.com/v1/${path}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey()}`,
    },
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    const detail = await response.text();
    throw new Error(`OpenAI ${path} failed (${response.status}): ${detail}`);
  }
  return await response.json();
}

export async function extractProfile(
  imageUrl: string,
): Promise<ExtractedProfile> {
  const result = (await callOpenAI("chat/completions", {
    model: "gpt-4o-mini",
    messages: [
      {
        role: "user",
        content: [
          { type: "text", text: EXTRACTION_PROMPT },
          { type: "image_url", image_url: { url: imageUrl, detail: "high" } },
        ],
      },
    ],
    response_format: {
      type: "json_schema",
      json_schema: {
        name: "profile_extraction",
        strict: true,
        schema: EXTRACTION_SCHEMA,
      },
    },
  })) as {
    choices?: Array<{ message?: { content?: string; refusal?: string } }>;
  };

  const message = result.choices?.[0]?.message;
  if (message === undefined || typeof message.content !== "string") {
    throw new Error(message?.refusal ?? "OpenAI returned no extraction");
  }
  const parsed = JSON.parse(message.content) as {
    is_profile: boolean;
    platform: string;
    name: string | null;
    handle: string | null;
    headline: string | null;
    bio: string | null;
  };

  const name = parsed.name?.trim() ?? "";
  if (!parsed.is_profile || name === "") {
    throw new Error("Could not read a profile in this screenshot");
  }
  const clean = (value: string | null): string | undefined => {
    const trimmed = value?.trim() ?? "";
    return trimmed === "" ? undefined : trimmed;
  };
  return {
    platform: parsed.platform,
    name,
    handle: clean(parsed.handle),
    headline: clean(parsed.headline),
    bio: clean(parsed.bio),
  };
}

export async function embedText(text: string): Promise<number[]> {
  const result = (await callOpenAI("embeddings", {
    model: "text-embedding-3-small",
    input: text,
  })) as { data?: Array<{ embedding?: number[] }> };

  const embedding = result.data?.[0]?.embedding;
  if (embedding === undefined) {
    throw new Error("OpenAI returned no embedding");
  }
  return embedding;
}

import {
  internalAction,
  internalMutation,
  internalQuery,
  mutation,
  query,
  QueryCtx,
  MutationCtx,
} from "./_generated/server";
import { v } from "convex/values";
import { getAuthUserId } from "@convex-dev/auth/server";
import { internal } from "./_generated/api";
import { Doc } from "./_generated/dataModel";
import { extractProfile } from "./openaiClient";

async function requireUser(ctx: QueryCtx | MutationCtx) {
  const userId = await getAuthUserId(ctx);
  if (userId === null) {
    throw new Error("Not signed in");
  }
  return userId;
}

const extractedValidator = v.object({
  platform: v.string(),
  name: v.string(),
  handle: v.optional(v.string()),
  headline: v.optional(v.string()),
  bio: v.optional(v.string()),
});

export const generateUploadUrl = mutation({
  args: {},
  returns: v.string(),
  handler: async (ctx) => {
    await requireUser(ctx);
    return await ctx.storage.generateUploadUrl();
  },
});

export const createCapture = mutation({
  args: { screenshotId: v.id("_storage") },
  returns: v.id("captures"),
  handler: async (ctx, args) => {
    const userId = await requireUser(ctx);
    const captureId = await ctx.db.insert("captures", {
      userId,
      screenshotId: args.screenshotId,
      status: "pending",
    });
    await ctx.scheduler.runAfter(0, internal.captures.extract, { captureId });
    return captureId;
  },
});

export const getCapture = internalQuery({
  args: { captureId: v.id("captures") },
  handler: async (ctx, args) => {
    return await ctx.db.get("captures", args.captureId);
  },
});

export const finishExtract = internalMutation({
  args: { captureId: v.id("captures"), extracted: extractedValidator },
  returns: v.null(),
  handler: async (ctx, args) => {
    const capture = await ctx.db.get("captures", args.captureId);
    if (capture === null) {
      return null; // discarded while extraction was running
    }
    await ctx.db.patch("captures", args.captureId, {
      status: "ready",
      extracted: args.extracted,
    });
    return null;
  },
});

export const failExtract = internalMutation({
  args: { captureId: v.id("captures"), error: v.string() },
  returns: v.null(),
  handler: async (ctx, args) => {
    const capture = await ctx.db.get("captures", args.captureId);
    if (capture === null) {
      return null;
    }
    await ctx.db.patch("captures", args.captureId, {
      status: "failed",
      error: args.error,
    });
    return null;
  },
});

export const extract = internalAction({
  args: { captureId: v.id("captures") },
  returns: v.null(),
  handler: async (ctx, args) => {
    const capture: Doc<"captures"> | null = await ctx.runQuery(
      internal.captures.getCapture,
      { captureId: args.captureId },
    );
    if (capture === null) {
      return null;
    }
    try {
      const imageUrl = await ctx.storage.getUrl(capture.screenshotId);
      if (imageUrl === null) {
        throw new Error("The screenshot file is missing");
      }
      const extracted = await extractProfile(imageUrl);
      await ctx.runMutation(internal.captures.finishExtract, {
        captureId: args.captureId,
        extracted,
      });
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Extraction failed";
      await ctx.runMutation(internal.captures.failExtract, {
        captureId: args.captureId,
        error: message,
      });
    }
    return null;
  },
});

export const listCaptures = query({
  args: {},
  returns: v.array(
    v.object({
      _id: v.id("captures"),
      _creationTime: v.number(),
      status: v.union(
        v.literal("pending"),
        v.literal("ready"),
        v.literal("failed"),
      ),
      extracted: v.optional(extractedValidator),
      error: v.optional(v.string()),
      imageUrl: v.union(v.string(), v.null()),
    }),
  ),
  handler: async (ctx) => {
    const userId = await requireUser(ctx);
    const captures = await ctx.db
      .query("captures")
      .withIndex("by_user", (q) => q.eq("userId", userId))
      .order("desc")
      .take(50);
    return await Promise.all(
      captures.map(async (capture) => ({
        _id: capture._id,
        _creationTime: capture._creationTime,
        status: capture.status,
        extracted: capture.extracted,
        error: capture.error,
        imageUrl: await ctx.storage.getUrl(capture.screenshotId),
      })),
    );
  },
});

export const acceptCapture = mutation({
  args: {
    captureId: v.id("captures"),
    link: v.optional(v.string()),
    context: v.optional(v.string()),
  },
  returns: v.id("people"),
  handler: async (ctx, args) => {
    const userId = await requireUser(ctx);
    const capture = await ctx.db.get("captures", args.captureId);
    if (capture === null || capture.userId !== userId) {
      throw new Error("Capture not found");
    }
    if (capture.status !== "ready" || capture.extracted === undefined) {
      throw new Error("Capture is not ready");
    }
    const personId = await ctx.db.insert("people", {
      userId,
      name: capture.extracted.name,
      link: args.link,
      context: args.context,
      updatedAt: Date.now(),
      platform: capture.extracted.platform,
      handle: capture.extracted.handle,
      headline: capture.extracted.headline,
      // The screenshot stays with the person as a visual memory anchor.
      screenshotId: capture.screenshotId,
    });
    await ctx.db.delete("captures", args.captureId);
    await ctx.scheduler.runAfter(0, internal.people.embed, { personId });
    return personId;
  },
});

export const discardCapture = mutation({
  args: { captureId: v.id("captures") },
  returns: v.null(),
  handler: async (ctx, args) => {
    const userId = await requireUser(ctx);
    const capture = await ctx.db.get("captures", args.captureId);
    if (capture === null || capture.userId !== userId) {
      throw new Error("Capture not found");
    }
    await ctx.storage.delete(capture.screenshotId);
    await ctx.db.delete("captures", args.captureId);
    return null;
  },
});

